**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <algorithm>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int K;
    plik >> K;
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);

    vector<int> sorted_tab = tab;
    sort(sorted_tab.begin(), sorted_tab.end());

    cout << "a) " << K << " najmniejszych:";
    double suma = 0;
    for (int i = 0; i < K; i++) {
        cout << " " << sorted_tab[i];
        suma += sorted_tab[i];
    }
    cout << endl;
    cout << fixed << setprecision(2);
    cout << "   Srednia: " << suma / K << endl;

    int n = sorted_tab.size();
    cout << "c) " << K << " najwiekszych:";
    for (int i = n - 1; i >= n - K; i--) {
        cout << " " << sorted_tab[i];
    }
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Sortujemy kopie tablicy. K pierwszych to najmniejsze (rosnaco). K ostatnich od konca to najwieksze (malejacej). Srednia = suma K najmniejszych / K.

Weryfikacja:
- Posortowane: 8, 12, 15, 23, 34, 39, 45, 56, 67, 78, 82, 91
- K=3 najmniejszych: 8, 12, 15. Srednia = (8+12+15)/3 = 35/3 = 11.67
- K=3 najwiekszych: 91, 82, 78.
